<!doctype html>
<html lang="id"><head><meta charset="utf-8"><title>Nomor Antrean</title><style>body{font-family:Arial,sans-serif}h1{text-align:center}.ticket{border:1px solid #222;padding:24px}.number{text-align:center;font-size:42px;font-weight:bold;margin:20px}</style></head>
<body><div class="ticket"><h1>Pelayanan Klaim Jaminan Kematian</h1><h2 style="text-align:center">Bukti Pengajuan</h2><div class="number">{{ $pengajuan->nomorAntrian->nomor_urut }}</div><p><strong>Jenis pelayanan:</strong> {{ $pengajuan->nomorAntrian->jenis_pelayanan }}</p><p><strong>Peserta:</strong> {{ $pengajuan->peserta->nama }}</p><p><strong>NIK:</strong> {{ $pengajuan->peserta->nik }}</p><p><strong>Nomor HP peserta:</strong> {{ $pengajuan->no_hp_peserta }}</p><p><strong>Ahli waris:</strong> {{ $pengajuan->nama_ahli_waris }}</p><p><strong>Nomor HP ahli waris:</strong> {{ $pengajuan->no_hp_ahli_waris }}</p><p><strong>Bank:</strong> {{ $pengajuan->nama_bank ?? 'Belum tercatat' }}</p><p><strong>Nomor rekening:</strong> {{ $pengajuan->nomor_rekening_ahli_waris }}</p><p><strong>Keterangan:</strong> {{ $pengajuan->keterangan_ahli_waris }}</p><p><strong>Loket:</strong> {{ $pengajuan->nomorAntrian->nomor_loket }}</p><p><strong>Waktu:</strong> {{ $pengajuan->nomorAntrian->waktu_pengambilan->format('d-m-Y H:i') }}</p><p><strong>Dokumen:</strong> Akta kematian, kartu BPJS, dan buku rekening telah diunggah.</p></div></body></html>
